-- 中文操作说明：共同照护目标独立三表；适用cn版，MySQL 5.7.18（允许供应商后缀，不支持MariaDB）。
-- 实际目标库由操作者明确选择并核对selected_schema；同一库root/cn只选一套，不交叉执行。
-- 前提：已有patient/sys_user的有符号BIGINT主键和InnoDB基础结构；普通家庭权限沿用现有服务。
-- 既有库：停写并验证备份可恢复 → 单独只读01 → 仅EXACT_OLD经批准执行02 → 单独只读03。
-- FULLY_INSTALLED跳过02；PARTIAL_OR_UNKNOWN或任何错误立即停止，不能盲重跑、补齐或删除审计模拟回滚。
-- 空库使用独立init successor，不能把init当升级，也不能在02之后再执行init；不重跑已安装旧SQL。
-- 核实SELECT/CREATE/TRIGGER/REFERENCES权限、可用空间、表大小和恢复方案；DDL隐式提交，可能等待元数据锁。
-- 不承诺在线无锁、原子回滚或固定耗时；失败保持停写，人工恢复或审定向前修复；禁止--force或忽略错误。
-- 不回填旧数值目标、临床数据、历史、关系或患者同意；功能开关默认false，不替操作者开启。
-- 使用已批准连接参数和交互密码：mysql --batch --default-character-set=utf8mb4 --host=HOST --port=PORT --user=USER --password --database=DB < SCRIPT.sql
-- 本文件：只读后检，必须输出FULLY_INSTALLED。只交付源文，原生MySQL运行/EXPLAIN/耗时及部署均未验证。
SELECT DATABASE() AS selected_schema,VERSION() AS server_version,CASE WHEN (SELECT CASE WHEN
  DATABASE() IS NOT NULL AND (VERSION()='5.7.18' OR VERSION() LIKE '5.7.18-%') AND LOWER(VERSION()) NOT LIKE '%mariadb%' AND (FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)>0) AND @@SESSION.foreign_key_checks=1 AND @@SESSION.unique_checks=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='patient' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='patient' AND BINARY COLUMN_NAME='id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND LOWER(EXTRA)='auto_increment')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='patient' AND BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE')=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='sys_user' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='sys_user' AND BINARY COLUMN_NAME='id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND LOWER(EXTRA)='auto_increment')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='sys_user' AND BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='patient' AND BINARY INDEX_NAME='PRIMARY')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='sys_user' AND BINARY INDEX_NAME='PRIMARY')=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY LEFT(TABLE_NAME,16)=BINARY 'common_care_goal')=3 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND ROW_FORMAT='Dynamic' AND TABLE_COLLATION='utf8mb4_bin')=1 AND
  (SELECT COUNT(*)=16 AND SUM(CASE WHEN (BINARY COLUMN_NAME='id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='auto_increment' AND ORDINAL_POSITION=1 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='patient_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=2 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='creator_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=3 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='title' AND LOWER(COLUMN_TYPE)='varchar(120)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=4 AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_bin') OR (BINARY COLUMN_NAME='goal_text' AND LOWER(COLUMN_TYPE)='varchar(1000)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=5 AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_bin') OR (BINARY COLUMN_NAME='progress_criterion' AND LOWER(COLUMN_TYPE)='varchar(500)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=6 AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_bin') OR (BINARY COLUMN_NAME='responsibility' AND LOWER(COLUMN_TYPE)='varchar(500)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=7 AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_bin') OR (BINARY COLUMN_NAME='review_date' AND LOWER(COLUMN_TYPE)='varchar(10)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=8 AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (BINARY COLUMN_NAME='nominee_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=9 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='state' AND LOWER(COLUMN_TYPE)='varchar(16)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=10 AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (BINARY COLUMN_NAME='version' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=11 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='cycle' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=12 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='accepted_by' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=13 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='accepted_at' AND LOWER(COLUMN_TYPE)='datetime(6)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=14 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='created_at' AND LOWER(COLUMN_TYPE)='datetime(6)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=15 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='updated_at' AND LOWER(COLUMN_TYPE)='datetime(6)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=16 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) THEN 1 ELSE 0 END)=16 FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal') AND
  (SELECT COUNT(*)=9 AND SUM(CASE WHEN (BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_goal' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='patient_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_goal' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=2 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_state' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='patient_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_state' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND BINARY COLUMN_NAME='state' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_state' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=3 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_creator' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='creator_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_nominee' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='nominee_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_accepted' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='accepted_by' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') THEN 1 ELSE 0 END)=9 FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal') AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='common_care_goal' AND BINARY k.CONSTRAINT_NAME='ccg57_goal_patient' AND BINARY k.COLUMN_NAME='patient_id' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.REFERENCED_TABLE_NAME='patient' AND BINARY k.REFERENCED_COLUMN_NAME='id' AND BINARY r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='common_care_goal' AND BINARY k.CONSTRAINT_NAME='ccg57_goal_creator' AND BINARY k.COLUMN_NAME='creator_id' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.REFERENCED_TABLE_NAME='sys_user' AND BINARY k.REFERENCED_COLUMN_NAME='id' AND BINARY r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='common_care_goal' AND BINARY k.CONSTRAINT_NAME='ccg57_goal_nominee' AND BINARY k.COLUMN_NAME='nominee_id' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.REFERENCED_TABLE_NAME='sys_user' AND BINARY k.REFERENCED_COLUMN_NAME='id' AND BINARY r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='common_care_goal' AND BINARY k.CONSTRAINT_NAME='ccg57_goal_accepted' AND BINARY k.COLUMN_NAME='accepted_by' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.REFERENCED_TABLE_NAME='sys_user' AND BINARY k.REFERENCED_COLUMN_NAME='id' AND BINARY r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal' AND REFERENCED_TABLE_NAME IS NOT NULL)=4 AND
  (SELECT COUNT(*)=6 AND SUM(CASE WHEN (BINARY CONSTRAINT_NAME='PRIMARY' AND CONSTRAINT_TYPE='PRIMARY KEY') OR (BINARY CONSTRAINT_NAME='ccg57_patient_goal' AND CONSTRAINT_TYPE='UNIQUE') OR (BINARY CONSTRAINT_NAME='ccg57_goal_patient' AND CONSTRAINT_TYPE='FOREIGN KEY') OR (BINARY CONSTRAINT_NAME='ccg57_goal_creator' AND CONSTRAINT_TYPE='FOREIGN KEY') OR (BINARY CONSTRAINT_NAME='ccg57_goal_nominee' AND CONSTRAINT_TYPE='FOREIGN KEY') OR (BINARY CONSTRAINT_NAME='ccg57_goal_accepted' AND CONSTRAINT_TYPE='FOREIGN KEY') THEN 1 ELSE 0 END)=6 FROM information_schema.TABLE_CONSTRAINTS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal') AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal_command' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND ROW_FORMAT='Dynamic' AND TABLE_COLLATION='utf8mb4_bin')=1 AND
  (SELECT COUNT(*)=9 AND SUM(CASE WHEN (BINARY COLUMN_NAME='actor_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=1 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='command_key' AND LOWER(COLUMN_TYPE)='varchar(36)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=2 AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (BINARY COLUMN_NAME='patient_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=3 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='goal_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=4 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='expected_version' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=5 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) OR (BINARY COLUMN_NAME='operation' AND LOWER(COLUMN_TYPE)='varchar(20)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=6 AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (BINARY COLUMN_NAME='payload_hash' AND LOWER(COLUMN_TYPE)='varchar(64)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=7 AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (BINARY COLUMN_NAME='result_json' AND LOWER(COLUMN_TYPE)='varchar(512)' AND IS_NULLABLE='YES' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=8 AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_bin') OR (BINARY COLUMN_NAME='created_at' AND LOWER(COLUMN_TYPE)='datetime(6)' AND IS_NULLABLE='NO' AND (BINARY COLUMN_DEFAULT <=> NULL) AND LOWER(EXTRA)='' AND ORDINAL_POSITION=9 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL) THEN 1 ELSE 0 END)=9 FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal_command') AND
  (SELECT COUNT(*)=7 AND SUM(CASE WHEN (BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='actor_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=2 AND BINARY COLUMN_NAME='command_key' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_actor_key' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='patient_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_actor_key' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=2 AND BINARY COLUMN_NAME='actor_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_patient_actor_key' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=3 AND BINARY COLUMN_NAME='command_key' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_command_goal' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='patient_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') OR (BINARY INDEX_NAME='ccg57_command_goal' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND BINARY COLUMN_NAME='goal_id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A') THEN 1 ELSE 0 END)=7 FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME='common_care_goal_command') AND
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='common_care_goal_command' AND BINARY k.CONSTRAINT_NAME='ccg57_command_actor' AND BINARY k.COLUMN_NAME='actor_id' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.REFERENCED_TABLE_NAME='sys_user' AND BINARY k.REFERENCED_COLUMN_NAME='id' AND BINARY r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
